#!/usr/bin/env bash
# Generated by cargo fallow hooks install.
# Installer version: @@INSTALLER_VERSION@@
# Native JSON protocol: cargo-fallow-gate-v1
#
# A Claude Code and Codex PreToolUse gate. Both send the tool payload as JSON
# on stdin and treat exit 2 as a block. The gate blocks a `git commit` or a
# `git push` of the agent when `cargo fallow check` fails an enforced gate on
# the changed files. The `cargo fallow hooks gate-runtime run` command does
# the work: it reads the payload, finds the git write, runs the check, writes
# the report and prints the block message.
#
# This script only finds the binary and keeps the gate open on an error. A
# missing binary, a bad payload or a crash of the runtime gives one line on
# stderr and exit 0. The gate blocks only on new findings: a finding that the
# base commit already has does not block.
#
# Settings:
#   CARGO_FALLOW_GATE_BIN          The cargo-fallow binary to run.
#   CARGO_FALLOW_GATE_MIN_VERSION  The lowest version of cargo-fallow that the
#                                  gate accepts. The default is the installer
#                                  version. An empty value turns the floor off.
#   CARGO_FALLOW_GATE_REPORT       The path of the JSON report. The default is
#                                  .fallow/cargo-gate-report.json in the
#                                  workspace root.
#   CARGO_FALLOW_GATE_DEBUG=1      Also log the commands that the gate skips.
set -u

PROTOCOL=cargo-fallow-gate-v1
MIN_VERSION="${CARGO_FALLOW_GATE_MIN_VERSION-@@INSTALLER_VERSION@@}"

INPUT="$(cat)"

# The hook runs on each shell command. A command that holds no `git` word with
# a later `commit`, `push` or expansion cannot be a git write, so the gate
# stops here and starts no process. Quote and escape characters go first, so
# `g''it commit` still goes on. A JSON `\u` escape can hide a word, so such a
# payload always goes on.
case "$INPUT" in
  *'\u'*) ;;
  *)
    case "${INPUT//[\'\"\\]/}" in
      *git*commit* | *git*push* | *git*'$'*) ;;
      *)
        if [ -n "${CARGO_FALLOW_GATE_DEBUG:-}" ]; then
          echo "cargo-fallow-gate: not a git commit or push, skipping the check." >&2
        fi
        exit 0
        ;;
    esac
    ;;
esac

BIN="${CARGO_FALLOW_GATE_BIN:-}"
if [ -z "$BIN" ]; then
  if command -v cargo-fallow >/dev/null 2>&1; then
    BIN="$(command -v cargo-fallow)"
  elif [ -x "${CARGO_HOME:-$HOME/.cargo}/bin/cargo-fallow" ]; then
    BIN="${CARGO_HOME:-$HOME/.cargo}/bin/cargo-fallow"
  fi
fi
if [ -z "$BIN" ] || [ ! -x "$BIN" ]; then
  echo "cargo-fallow-gate: cargo-fallow not found (tried CARGO_FALLOW_GATE_BIN, PATH and ~/.cargo/bin), skipping the check." >&2
  exit 0
fi

# A probe never gets the payload on stdin. A binary without the runtime
# command prints no protocol line.
PROBE="$("$BIN" hooks gate-runtime probe </dev/null 2>/dev/null || true)"
VERSION="${PROBE#"$PROTOCOL "}"
if [ "$VERSION" = "$PROBE" ]; then
  if [ -z "$MIN_VERSION" ]; then
    echo "cargo-fallow-gate: $BIN has no gate runtime, skipping the check." >&2
    exit 0
  fi
  VERSION_LINE="$("$BIN" --version 2>/dev/null || true)"
  VERSION="${VERSION_LINE#cargo-fallow }"
  VERSION="${VERSION%% *}"
  BELOW=1
else
  BELOW=0
fi
if [ -n "$MIN_VERSION" ] && [ "$BELOW" -eq 0 ]; then
  LOWER="$(printf '%s\n%s\n' "$MIN_VERSION" "$VERSION" | sort -V | head -n 1)"
  [ "$LOWER" = "$MIN_VERSION" ] || BELOW=1
fi
if [ "$BELOW" -eq 1 ]; then
  {
    echo "cargo-fallow-gate: blocked: $BIN is cargo-fallow ${VERSION:-unknown}, below the required $MIN_VERSION."
    echo "cargo-fallow-gate: upgrade it with \`cargo install cargo-fallow\`, or set CARGO_FALLOW_GATE_MIN_VERSION= to turn the floor off."
  } >&2
  exit 2
fi

if ! OUT_FILE="$(mktemp)" || ! ERR_FILE="$(mktemp)"; then
  echo "cargo-fallow-gate: cannot make a temporary file, skipping the check." >&2
  exit 0
fi
trap 'rm -f "$OUT_FILE" "$ERR_FILE"' EXIT

# The manifest that install recorded, relative to the install root. The
# runtime uses it when no Cargo.toml is above the session folder.
MANIFEST="@@MANIFEST@@"
if [ -n "$MANIFEST" ]; then
  INSTALL_ROOT="$(CDPATH='' cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." 2>/dev/null && pwd -P)" || INSTALL_ROOT=""
  if [ -n "$INSTALL_ROOT" ]; then
    export CARGO_FALLOW_GATE_MANIFEST="$INSTALL_ROOT/$MANIFEST"
  fi
fi

# The runtime blocks with exit code 1 and the block line on stdout. Each other
# result keeps the gate open: a usage error of an old binary exits 2, and a
# panic exits 101. A pinned toolchain that is not installed must not start a
# download in the hook. The subshell sends the note of bash about a killed
# process to the error file too.
STATUS=0
(
  RUSTUP_AUTO_INSTALL=0 "$BIN" hooks gate-runtime run <<<"$INPUT" >"$OUT_FILE"
  # A second command keeps bash from an exec of the runtime, so this
  # subshell writes the note.
  exit "$?"
) 2>"$ERR_FILE" || STATUS=$?

if [ "$STATUS" -eq 1 ] && grep -qx "$PROTOCOL block" "$OUT_FILE"; then
  cat "$ERR_FILE" >&2
  exit 2
fi
if [ "$STATUS" -eq 0 ]; then
  # A pass prints at most one notice line.
  sed -n '1p' "$ERR_FILE" >&2
  exit 0
fi
FIRST_LINE="$(sed -n '1p' "$ERR_FILE")"
echo "cargo-fallow-gate: the gate runtime stopped with exit code $STATUS${FIRST_LINE:+ ($FIRST_LINE)}, skipping the check." >&2
exit 0
